tool_calls.arguments:
{"command":"kubectl -n default patch deploy app --type=strategic -p '{
  "spec": {
    "template": {
      "spec": {
        "containers": [
          {
            "name": "app",
            "livenessProbe": {
              "httpGet": {"path": "/", "port": 80, "scheme": "HTTP"},
              "initialDelaySeconds": 5,
              "periodSeconds": 5,
              "failureThreshold": 3
            },
            "startupProbe": {
              "httpGet": {"path": "/", "port": 80, "scheme": "HTTP"},
              "initialDelaySeconds": 3,
              "periodSeconds": 5,
              "failureThreshold": 3
            }
          }
        ]
      }
    }
  }
}'"}

{"command":"echo "=== deployment conditions ==="
kubectl -n default get deploy app -o jsonpath='{range .status.conditions[*]}{.type}{" "}{.status}{" "}{.reason}{"\n"}{end}'
echo "=== new replicaset pods, restarts/started ==="
kubectl -n default get pods -l app=app -o jsonpath='{range .items[*]}{.metadata.name}{" restarts="}{.status.containerStatuses[0].restartCount}{" started="}{.status.containerStatuses[0].started}{" ready="}{.status.containerStatuses[0].ready}{"\n"}{end}'
echo "=== probe results on new pods ==="
kubectl -n default exec deploy/app -- bash -c 'for p in $(kubectl get pods -l app=app -o name); do 
  r=$(curl -s -o /dev/null -w "readiness(/:80)=%{http_code}\n" http://127.0.0.1/);
  l=$(curl -s -o /dev/null -w "liveness(//:80)=%{http_code}\n" http://127.0.0.1/);
  echo "pod $p readiness=$r liveness=$l";
done'"}

